const duplicateNumbers = [1, 1, 2, 3, 3, 4, 5, 5];

// 1. Array deduplication trick
const uniqueArray = [...new Set(duplicateNumbers)];
console.log(uniqueArray); // [1, 2, 3, 4, 5]

// 2. High performance lookups
const blockedIPs = new Set(['192.168.1.1', '10.0.0.5']);

// Instant O(1) lookup. Much faster than arrays!
if (blockedIPs.has('192.168.1.1')) {
  console.log('Access Denied');
}
